WITH RecursiveTypeSums AS (
    SELECT
        pt.Id AS PostTypeId,
        pt.Name AS PostTypeName,
        COALESCE(SUM(p.Score),0) AS TotalScore,
        COUNT(*) AS TotalPosts
    FROM Posts p
    RIGHT JOIN PostTypes pt ON p.PostTypeId = pt.Id
    GROUP BY pt.Id, pt.Name
),
UserPostParticipation AS (
    SELECT 
        u.Id AS UserId,
        u.DisplayName,
        u.Reputation,
        COUNT(p.Id) AS NumberOfPosts, 
        SUM(COALESCE(p.Score, 0)) AS SumPostScore,
        COUNT(DISTINCT CASE WHEN p.AcceptedAnswerId IS NOT NULL THEN p.AcceptedAnswerId END) AS AcceptedCount,
        ROW_NUMBER() OVER (PARTITION BY u.Id ORDER BY p.CreationDate DESC) AS rn_latest_post,
        MAX(p.CreationDate) AS LastPostDate
    FROM Users u 
    LEFT JOIN Posts p ON p.OwnerUserId = u.Id
    GROUP BY u.Id, u.DisplayName, u.Reputation
),
